function priceMarkup(p,detail=false){const price=priceReferences[p.id];if(!price)return `<p class="reference-price price-unavailable">Price on request</p>`;const amount=new Intl.NumberFormat('en-ZA',{style:'currency',currency:price.currency}).format(price.amountMinor/100);return `<div class="reference-price"><span>Indicative price</span><strong>${esc(amount)}</strong><small>${p.unit==='Each'?'each':'per '+esc(p.unit.toLowerCase())}</small></div>${detail?`<p class="help">Final price by quotation. Delivery excluded.</p><details class="price-basis"><summary>Price reference</summary><p>Retail benchmark checked ${esc(price.checkedOn)} at <a href="${esc(price.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(price.retailer)}</a>.</p><p>${esc(price.referenceProduct)}</p><p>${esc(price.basis)}</p><p>${esc(price.taxBasis)} Retail promotions may change. This does not confirm Lepetse stock or selling prices.</p></details>`:''}`}
function productBrand(p){return /^(?:To be confirmed|Not specified|Brand to be confirmed)$/i.test(p.brand)?"Brand to be confirmed":p.brand}
function productArt(p){return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}${p.imageType==='supplier product photograph'?' — product photograph':' — generated illustrative product image'}" width="900" height="900" loading="lazy" decoding="async">`:`<div class="product-placeholder">${icon(p.category)}<span>Illustration</span></div>`}
function cardName(p){const brand=productBrand(p);if(brand==='Brand to be confirmed')return p.name;let name=p.name;if(name.toLowerCase().startsWith('waltons '+brand.toLowerCase()+' '))name=name.slice(8);const prefix=brand.split(/[^a-z0-9]+/i).filter(Boolean).join('[\\s-]+');return name.replace(new RegExp('^'+prefix+'\\s+','i'),'')}
function cardSpecification(p){const unit=p.unit.toLowerCase();return p.summary.split(/\s*·\s*/).filter(part=>{const text=part.toLowerCase();return text!=='each'&&text!==unit&&!(/^(?:pack|set|box) of \d+$/i.test(part)&&unit.startsWith(text))}).join(' · ')}
function cardPrice(p){const price=priceReferences[p.id];const unit=p.unit==='Each'?'each':'per '+p.unit.toLowerCase();if(!price)return `<div class="card-price"><div class="card-price-line"><strong class="on-request">Price on request</strong></div><small>${esc(unit)}</small></div>`;const amount=new Intl.NumberFormat('en-ZA',{style:'currency',currency:price.currency}).format(price.amountMinor/100);return `<div class="card-price"><div class="card-price-line"><strong>${esc(amount)}</strong><span>${esc(unit)}</span></div><small>Indicative price · final price by quotation</small></div>`}
function productCard(p){return `<article class="product-card"><a class="product-image" href="#product-${p.id}" aria-label="View ${esc(p.name)}">${productArt(p)}</a><div class="product-body"><span class="product-brand">${esc(productBrand(p))}</span><h3><a href="#product-${p.id}" title="${esc(p.name)}">${esc(cardName(p))}</a></h3><p class="card-specification" title="${esc(cardSpecification(p))}">${esc(cardSpecification(p))}</p>${cardPrice(p)}<div class="product-controls"><label class="sr-only" for="qty-${p.id}">Quantity for ${esc(p.name)} (${esc(p.unit)})</label><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button class="btn dark" data-product="${p.id}">Add to quote</button></div></div></article>`}
function addProduct(id,quantity){const p=products.find(p=>p.id===id);if(!p)return;if(!Number.isInteger(quantity)||quantity<1||quantity>999999){toast('Enter a whole quantity between 1 and 999,999.');return}const existing=items.find(i=>i.productId===id);const total=Number(existing?.quantity||0)+quantity;if(total>999999){toast('This would exceed the maximum quantity of 999,999. Edit the basket first.');return}if(existing)existing.quantity=total;else items.push({productId:p.id,description:`${p.name} — ${p.summary}`,quantity,unit:p.unit});updateCount();showAdded(p,quantity,total)}
function bindProducts(){main.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>addProduct(b.dataset.product,Number(document.getElementById('qty-'+b.dataset.product).value)));}
function productPage(id){const p=products.find(p=>p.id===id);if(!p&&retiredProducts.some(x=>x.id===id)){const retired=retiredProducts.find(x=>x.id===id),replacement=products.find(x=>x.id===retired.replacementId);return pageHero('Catalogue update','This product has been updated','Review the current product specifications and ordering unit before adding it to your quote.')+`<section class="section"><div class="wrap"><a class="btn dark" href="#product-${replacement.id}">View ${esc(replacement.name)}</a></div></section>`}if(!p)return pageHero('Catalogue','Product not found','Browse the catalogue to select a product.')+'<div class="wrap section"><a href="#stationery">Back to products</a></div>';return `<section class="section product-detail"><div class="wrap"><a class="breadcrumb" href="${catalogueHref()}">← Back to results</a><div class="product-detail-grid"><div class="detail-image">${productArt(p)}</div><div><span class="eyebrow">${p.supplierReference?'Product details':'Sample product'}</span><h1>${p.name}</h1><p>${p.summary}</p>${priceMarkup(p,true)}<dl class="product-specifications">${Object.entries(p.specs).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>Order unit</dt><dd>${p.unit}</dd></div><div><dt>Brand</dt><dd>${esc(productBrand(p))}</dd></div></dl><label for="qty-${p.id}" class="qty-detail-label">Quantity (${p.unit.toLowerCase()})</label><div class="product-controls detail-controls"><input id="qty-${p.id}" type="number" min="1" max="999999" step="1" value="1"><button class="btn dark" data-product="${p.id}">Add to quote basket</button></div><p class="help">${p.supplierReference?'Product photograph from the supplier catalogue. Packaging may vary. Availability and lead time will be confirmed in your quotation.':'Generated image for illustration. Final brand, specifications and availability to be confirmed.'}</p><a class="text-link" href="#basket">Review your quote basket</a></div></div></div></section>`}
function basket(){if(!items.length)return pageHero('Quotation request','Your quote basket is empty','Choose products and quantities, or attach an existing stationery list.')+`<section class="section"><div class="wrap"><div class="empty empty-basket"><h2>Start your enquiry</h2><p>Catalogue selections will be saved on this device. No order is placed until pricing and terms are agreed.</p><a class="btn dark" href="#stationery">Browse products</a><a class="btn outline" href="#upload">Upload your list</a></div></div></section>`;return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Quotation request</span><h1>Your quote basket</h1><p>Review specifications, quantities and order units before entering your contact and delivery details.</p></div></section><section class="section basket-section"><div class="wrap basket-layout"><div>${items.length?`<div class="basket-items">${items.map((x,i)=>{const p=products.find(p=>p.id===x.productId);return `<article class="basket-item">${p?`<div class="basket-thumb">${productArt(p)}</div>`:''}<div class="basket-description"><h2>${esc(x.description)}</h2><p>Order unit: ${esc(x.unit||'Specify pack size in the request')}</p><span>Pricing to be confirmed</span></div><div><label for="basket-qty-${i}">Quantity</label><input id="basket-qty-${i}" type="number" min="1" max="999999" step="1" value="${esc(x.quantity)}" data-basket-qty="${i}"><button class="remove-item" data-basket-remove="${i}">Remove</button></div></article>`}).join('')}</div><div class="basket-footer-actions"><a class="text-link" href="#stationery">Continue browsing</a><button class="clear-filters" id="clear-basket">Clear basket</button></div>`:`<div class="empty"><h2>Your quote basket is empty</h2><p>Start with products from the catalogue, or upload an existing list. No order has been placed.</p><a class="btn dark" href="#stationery">Browse products</a><a class="btn outline" href="#upload">Upload your list</a></div>`}</div><aside class="basket-summary"><h2>Request summary</h2><p class="basket-storage-note">${items.some(x=>retiredProducts.some(p=>p.id===x.productId))?'Some selections are from the previous catalogue. Their original descriptions, quantities and units have been retained. Review them before requesting a quote.':basketStorageUnavailable?'Device storage is unavailable. Keep this page open to retain your selections.':'Catalogue selections are saved on this device. Contact details and attachments are not saved.'}</p><dl><div><dt>Item lines</dt><dd>${items.length}</dd></div><div><dt>Prices and availability</dt><dd>To be quoted</dd></div><div><dt>Delivery charges</dt><dd>Subject to location</dd></div></dl><p>Amounts and applicable VAT will be included in the quotation. Mixed packs and units are kept separate.</p>${items.length?'<button class="btn dark" id="basket-continue">Continue to enquiry</button>':''}<a class="btn outline" href="#upload">Upload your list</a><p class="help">Prototype: the enquiry can be downloaded for review. Nothing is sent to Lepetse.</p></aside></div></section>`}
function bindBasket(){$('#clear-basket')?.addEventListener('click',clearBasketPrompt);main.querySelectorAll('[data-basket-qty]').forEach(e=>{e.oninput=()=>{const q=Number(e.value);if(Number.isInteger(q)&&q>=1&&q<=999999){items[Number(e.dataset.basketQty)].quantity=q;saveBasket()}};e.onchange=()=>{if(!e.checkValidity()){e.value=items[Number(e.dataset.basketQty)].quantity;toast('Enter a whole quantity between 1 and 999,999.')}}});main.querySelectorAll('[data-basket-remove]').forEach(e=>e.onclick=()=>{items.splice(Number(e.dataset.basketRemove),1);main.innerHTML=basket();bindBasket();updateCount()});$('#basket-continue')?.addEventListener('click',()=>{const bad=[...main.querySelectorAll('[data-basket-qty]')].find(e=>!e.value||!e.checkValidity());if(bad){bad.reportValidity();return}capture();step=0;location.hash='quote'})}
